/* ACERCA · aplicación funcional */
const LEAVE_TYPES=['Hospitalización','Mudanza','Fallecimiento','Paternidad / maternidad','Deber inexcusable','Matrimonio propio','Matrimonio de terceros','Fuerza mayor','Horas médicas','Juicio','Ausencia justificada no retribuida','Ausencia injustificada','Baja médica'];
const state={page:'inicio',workers:[],societies:[],vacations:[],leaves:[],incidents:[],partners:[],hours:[],payments:[],obligations:[],pending:[],filters:{},analysis:{},calendarYear:new Date().getFullYear(),calendarMonth:new Date().getMonth()};
const titles={inicio:'Inicio',trabajadores:'Trabajadores',vacaciones:'Vacaciones',permisos:'Permisos y ausencias',incidencias:'Impuntualidades y abandonos',partners:'Partners',horas:'Horas extra',pagos:'Pagos adicionales',pendientes:'Pagos pendientes',bonos:'Bonos de asistencia',analisis:'Análisis',configuracion:'Configuración'};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isoDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const today=()=>isoDate(new Date());
const money=v=>Number(v||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('es-ES'):'-';
const client=()=>window.ACERCA_SUPABASE;
function toast(m){const e=$('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3200);}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('show');}
function closeModal(){$('modal').classList.remove('show');}
function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function normalizeCompany(s){const n=norm(s);return (state.societies||[]).find(x=>norm(x.name)===n)?.name||null;}
function workerName(id){const w=state.workers.find(x=>x.id===id);return w?w.agent:'Trabajador eliminado';}
function workerOptions(){return '<option value="">Seleccionar trabajador</option>'+state.workers.map(w=>'<option value="'+esc(w.id)+'">'+esc(w.agent)+' · '+esc(w.company)+'</option>').join('');}
const iconPaths={home:'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="5" rx="1.5"/><rect x="13" y="10" width="8" height="11" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',handshake:'<path d="m11 17 2 2a2 2 0 0 0 3-3"/><path d="m14 14 4 4a2 2 0 0 0 3-3l-7-7-4 1-3-2-5 5a2 2 0 0 0 3 3l3-3"/><path d="m2 12 3 3m12-2 3-3M7 7l3-3 4 1 3-1 4 4"/>',coins:'<circle cx="8" cy="8" r="6"/><path d="M18.09 10.37A6 6 0 1 1 10.34 18M8 6v4l2 1m8-2v8m-4-4h8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.7 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.7-1l-1.7.7-1.4-2.4L7.3 15a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.7-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.7 1l1.7-.7 1.4 2.4L19.4 13a8 8 0 0 1 0 2Z"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
function icon(name,cls=''){return '<svg class="'+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(iconPaths[name]||iconPaths.file)+'</svg>';}
function field(label,name,type='text',required=true,extra=''){return '<div class="field"><label for="'+name+'">'+label+'</label><input id="'+name+'" name="'+name+'" type="'+type+'" '+(required?'required':'')+' '+extra+'></div>';}
function selectField(label,name,options,required=true){return '<div class="field"><label for="'+name+'">'+label+'</label><select id="'+name+'" name="'+name+'" '+(required?'required':'')+'>'+options+'</select></div>';}
function textarea(label,name){return '<div class="field"><label for="'+name+'">'+label+'</label><textarea id="'+name+'" name="'+name+'" rows="2"></textarea></div>';}
function checkbox(label,name,checked=false){return '<div class="field"><label style="display:flex;gap:8px;align-items:center"><input style="width:auto" type="checkbox" id="'+name+'" '+(checked?'checked':'')+'> '+label+'</label></div>';}
function formWrap(title,body,submit,handler){modal(title,'<form id="recordForm" onsubmit="'+handler+'(event)">'+body+'<div id="formStatus" class="notice">Los datos se guardarán en Supabase.</div><div class="actions" style="justify-content:flex-end"><button class="btn primary" id="saveBtn" type="submit">'+submit+'</button></div></form>');}
async function insert(table,row){const {data,error}=await client().from(table).insert(row).select().single();if(error)throw error;return data;}
async function update(table,id,patch){const {error}=await client().from(table).update(patch).eq('id',id);if(error)throw error;}
async function remove(table,id){const prompt=table==='vacation_records'?'¿Eliminar este periodo de vacaciones? Esta acción no se puede deshacer.':'¿Seguro que quieres eliminar este registro?';if(!confirm(prompt))return;const {error}=await client().from(table).delete().eq('id',id);if(error){toast(error.message);return;}if(table==='vacation_records')closeModal();await loadAll();toast(table==='vacation_records'?'Periodo de vacaciones eliminado.':'Registro eliminado.');}
async function loadAll(){
 const db=client();if(!db)return;
  const specs=[['workers','workers','agent'],['societies','societies','name'],['vacation_records','vacations','start_date'],['leave_records','leaves','start_date'],['incident_records','incidents','incident_date'],['partner_records','partners','incorporation_date'],['extra_hours','hours','work_date'],['additional_payments','payments','payment_date'],['additional_payment_obligations','obligations','payroll_month'],['pending_payments','pending','expected_date']];
 const errors=[];
 await Promise.all(specs.map(async([table,key,sort])=>{const {data,error}=await db.from(table).select('*').order(sort,{ascending:false});if(error){state[key]=[];errors.push(table+': '+error.message);}else state[key]=data||[];}));
 if(errors.length)console.warn('Tablas pendientes de configurar:',errors);
 if(!errors.some(x=>x.startsWith('additional_payment_obligations:'))){try{await syncPaymentObligations();}catch(error){console.error('No se han podido actualizar los pagos previstos:',error);}}
 render();
 if(errors.length)toast('No se han podido cargar algunos módulos. Comprueba que has ejecutado supabase/acerca-modules.sql en Supabase.');
}
function firstFullPayrollMonth(worker){if(!worker?.hire_date)return null;const hire=new Date(worker.hire_date+'T12:00:00');if(Number.isNaN(hire.getTime()))return null;const month=new Date(hire.getFullYear(),hire.getMonth(),1);if(hire.getDate()>1)month.setMonth(month.getMonth()+1);const start=isoDate(month),end=isoDate(new Date(month.getFullYear(),month.getMonth()+1,0));if(worker.termination_date&&worker.termination_date<end)return null;return start;}
async function syncPaymentObligations(){const db=client();const {data:existing,error}=await db.from('additional_payment_obligations').select('*');if(error)throw error;const current=existing||[],byId=new Map(state.workers.map(w=>[w.id,w])),partnerById=new Map(state.partners.map(p=>[p.id,p]));const candidates=[];for(const w of state.workers){const month=firstFullPayrollMonth(w);if(month&&!current.some(x=>x.obligation_type==='Formación'&&x.worker_id===w.id))candidates.push({worker_id:w.id,obligation_type:'Formación',payroll_month:month,amount:null,notes:'Pago de formación correspondiente a la primera nómina mensual completa.'});}for(const p of state.partners){const w=byId.get(p.referred_worker_id);const month=firstFullPayrollMonth(w);if(month&&p.status!=='Cancelado'&&p.status!=='Abonado'&&!current.some(x=>x.obligation_type==='Incentivo Partner'&&x.partner_record_id===p.id))candidates.push({worker_id:w.id,partner_record_id:p.id,obligation_type:'Incentivo Partner',payroll_month:month,amount:100,notes:'Incentivo de 100 € por referido al completar su primer mes de nómina.'});}
 const stale=current.filter(x=>x.status!=='Abonado'&&x.status!=='No corresponde').filter(x=>{const worker=byId.get(x.worker_id),partner=x.partner_record_id?partnerById.get(x.partner_record_id):null;return !worker||firstFullPayrollMonth(worker)!==x.payroll_month||(x.obligation_type==='Incentivo Partner'&&(!partner||partner.status==='Cancelado'));});
 if(stale.length){const {error:cancelError}=await db.from('additional_payment_obligations').update({status:'No corresponde'}).in('id',stale.map(x=>x.id));if(cancelError)throw cancelError;}
 if(candidates.length){const {error:insertError}=await db.from('additional_payment_obligations').insert(candidates);if(insertError&&insertError.code!=='23505')throw insertError;}
 const {data:latest,error:reloadError}=await db.from('additional_payment_obligations').select('*').order('payroll_month',{ascending:false});if(reloadError)throw reloadError;state.obligations=latest||[];
}
function dateFilter(key){const f=state.filters[key]||{};return '<form class="toolbar range" onsubmit="applyFilter(event,\''+key+'\')"><label>Desde<input id="from-'+key+'" type="date" value="'+(f.from||isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1)))+'"></label><label>Hasta<input id="to-'+key+'" type="date" value="'+(f.to||today())+'"></label><button class="btn">Aplicar filtro</button><button class="btn" type="button" onclick="resetFilter(\''+key+'\')">Restablecer</button></form>';}
function applyFilter(e,k){e.preventDefault();const from=$('from-'+k).value,to=$('to-'+k).value;if(from&&to&&from>to){toast('La fecha inicial no puede ser posterior a la final.');return;}state.filters[k]={from,to};render();}
function resetFilter(k){delete state.filters[k];render();}
function inRange(date,key){const f=state.filters[key];return !f||(!f.from||date>=f.from)&&(!f.to||date<=f.to);}
function overlapsRange(start,end,key){const f=state.filters[key];return !f||(!f.from||end>=f.from)&&(!f.to||start<=f.to);}
function table(headers,rows,empty){return '<div class="card tablewrap"><table class="table"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td class="empty-state" colspan="'+headers.length+'"><div class="empty-icon">'+icon('file')+'</div><strong>'+empty+'</strong><br>No existen movimientos registrados.</td></tr>')+'</tbody></table></div>';}
function stat(label,value,sub,onClick){const key=/trabajador/i.test(label)?'users':/vacacion|asignaci|disfrutad/i.test(label)?'calendar':/incidencia|hora|semana/i.test(label)?'clock':/pag|bono|importe/i.test(label)?'coins':'file';return '<div class="card stat'+(onClick?' clickable':'')+'"'+(onClick?' role="button" tabindex="0" onclick="'+onClick+'" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();'+onClick+'}"':'')+'><div class="stathead"><span>'+label+'</span><span class="staticon">'+icon(key)+'</span></div><div class="value">'+value+'</div><div class="foot">'+sub+'</div></div>';}
function header(section,title,desc,action){return '<div class="head"><div><div class="eyebrow">'+section+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="actions">'+(action||'')+'</div></div>';}
function actionDelete(table,id){return '<button class="btn" onclick="removeRecord(\''+table+'\',\''+id+'\')">Eliminar</button>';}
function renderWorkers(){return table(['Agente','Sociedad','Mail','Fecha alta','Fecha baja','Motivo','Acciones'],state.workers.filter(w=>inRange(w.hire_date,'workers')).map(w=>'<tr><td>'+esc(w.agent)+'</td><td>'+esc(w.company)+'</td><td>'+esc(w.email||'-')+'</td><td>'+fmt(w.hire_date)+'</td><td>'+fmt(w.termination_date)+'</td><td>'+esc(w.termination_reason||'—')+'</td><td><button class="btn" onclick="editWorker(\''+w.id+'\')">Editar ficha</button></td></tr>'),'Todavía no hay trabajadores registrados.');}
function editWorker(id){const w=state.workers.find(x=>x.id===id);if(!w)return;formWrap('Editar ficha de trabajador',field('Nombre y apellidos','agent','text',true,'value="'+esc(w.agent)+'"')+selectField('Sociedad','company',societyOptions(w.company))+field('Mail corporativo (opcional)','email','email',false,'value="'+esc(w.email==='-'?'':w.email||'')+'"')+field('Fecha de alta','hire_date','date',true,'value="'+esc(w.hire_date)+'"')+field('Fecha de baja','termination_date','date',false,'value="'+esc(w.termination_date||'')+'"')+textarea('Motivo de finalización','termination_reason'),'Guardar cambios','saveWorkerEdit');$('termination_reason').value=w.termination_reason||'';window.editingWorkerId=id;}
async function saveWorkerEdit(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus'),id=window.editingWorkerId;b.disabled=true;try{const hire=$('hire_date').value,term=$('termination_date').value||null,email=$('email').value.trim().toLowerCase()||'-';if(term&&term<hire)throw Error('La fecha de baja no puede ser anterior al alta.');if(email!=='-'&&state.workers.some(w=>w.id!==id&&String(w.email||'').toLowerCase()===email))throw Error('Ya existe otro trabajador con ese correo.');await update('workers',id,{agent:$('agent').value.trim(),company:$('company').value,email,hire_date:hire,termination_date:term,termination_reason:$('termination_reason').value.trim()||null});closeModal();await loadAll();toast('Ficha actualizada.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function societyOptions(selected=''){return '<option value="">Seleccionar sociedad</option>'+state.societies.filter(x=>x.active||x.name===selected).map(x=>'<option '+(x.name===selected?'selected':'')+'>'+esc(x.name)+'</option>').join('');}
function showSocietyForm(name=''){const current=state.societies.find(x=>x.name===name);window.editingSocietyName=current?.name||null;formWrap(current?'Modificar sociedad':'Añadir sociedad',field('Nombre de la sociedad','society_name','text',true,'value="'+esc(current?.name||'')+'"')+'<div class="notice">El nombre se actualizará también en las fichas históricas que la utilizan.</div>',current?'Guardar cambios':'Añadir sociedad','saveSociety');}
async function saveSociety(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus'),old=window.editingSocietyName,name=$('society_name').value.trim();b.disabled=true;try{if(!name)throw Error('Indica el nombre de la sociedad.');if(state.societies.some(x=>norm(x.name)===norm(name)&&x.name!==old))throw Error('Ya existe una sociedad con ese nombre.');const db=client();const result=old?await db.from('societies').update({name,updated_at:new Date().toISOString()}).eq('name',old):await db.from('societies').insert({name});if(result.error)throw result.error;closeModal();await loadAll();toast(old?'Sociedad actualizada.':'Sociedad añadida.');}catch(err){s.textContent=err.message;b.disabled=false;}}
async function toggleSociety(name){const society=state.societies.find(x=>x.name===name);if(!society)return;const {error}=await client().from('societies').update({active:!society.active,updated_at:new Date().toISOString()}).eq('name',name);if(error){toast(error.message);return;}await loadAll();toast(society.active?'Sociedad desactivada.':'Sociedad activada.');}
function showNewWorker(){formWrap('Nuevo trabajador',field('Nombre y apellidos','agent')+selectField('Sociedad','company',societyOptions())+field('Mail corporativo (opcional)','email','email',false)+field('Fecha de alta','hire_date','date')+field('Fecha de baja','termination_date','date',false)+textarea('Motivo de finalización','termination_reason'),'Guardar trabajador','saveWorker');}
async function saveWorker(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const hire=$('hire_date').value,term=$('termination_date').value||null,email=$('email').value.trim().toLowerCase()||'-';if(term&&term<hire)throw Error('La fecha de baja no puede ser anterior al alta.');if(email!=='-'&&state.workers.some(w=>String(w.email||'').toLowerCase()===email))throw Error('Ya existe un trabajador con ese correo.');await insert('workers',{agent:$('agent').value.trim(),company:$('company').value,email,hire_date:hire,termination_date:term,termination_reason:$('termination_reason').value.trim()||null});closeModal();await loadAll();toast('Trabajador guardado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function downloadWorkersTemplate(){const rows=[['AGENTE','SOCIEDAD','MAIL','FECHA ALTA','FECHA DE BAJA'],['','','','','']];const ws=XLSX.utils.aoa_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Trabajadores');XLSX.writeFile(wb,'plantilla-trabajadores-acerca.xlsx');}
function showExcelImport(){modal('Importación masiva de trabajadores','<p>La plantilla conserva el formato de la hoja utilizada por ACERCA. También puedes subir otra hoja si mantiene los encabezados.</p><div class="notice">Columnas: AGENTE, SOCIEDAD, MAIL, FECHA ALTA y FECHA DE BAJA. El motivo de finalización se puede añadir en una sexta columna.</div><div class="actions"><button class="btn" type="button" onclick="downloadWorkersTemplate()">'+icon('download')+' Descargar plantilla</button></div><div class="field"><label>Archivo Excel (.xlsx o .xls)</label><input id="workersExcel" type="file" accept=".xlsx,.xls,.csv"></div><div id="workersImportStatus" class="notice">Selecciona el archivo para ver la vista previa.</div><div id="workersImportPreview"></div><div class="actions" style="justify-content:flex-end"><button class="btn primary" id="confirmWorkersImport" type="button" disabled>Importar trabajadores</button></div>');window.pendingWorkersImport=null;$('workersExcel').addEventListener('change',previewExcel);$('confirmWorkersImport').addEventListener('click',saveWorkersExcel);}
function excelDate(v){if(v===null||v===undefined||v==='')return null;if(v instanceof Date&&!isNaN(v))return [v.getFullYear(),String(v.getMonth()+1).padStart(2,'0'),String(v.getDate()).padStart(2,'0')].join('-');if(typeof v==='number'&&window.XLSX){const d=XLSX.SSF.parse_date_code(v);if(d)return [d.y,String(d.m).padStart(2,'0'),String(d.d).padStart(2,'0')].join('-');}const s=String(v).trim();if(!s||s==='-')return null;let m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');m=s.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);if(m)return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');const d=new Date(s);return isNaN(d)?'INVALID':[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function findHeader(headers,aliases){return headers.findIndex(h=>aliases.some(a=>norm(h)===norm(a)||norm(h).includes(norm(a))||norm(a).includes(norm(h))&&norm(h).length>3));}
async function previewExcelRaw(e){const f=e.target.files?.[0],status=$('workersImportStatus'),preview=$('workersImportPreview'),btn=$('confirmWorkersImport');btn.disabled=true;preview.innerHTML='';window.pendingWorkersImport=null;if(!f)return;try{if(!window.XLSX)throw Error('No se ha cargado el lector Excel. Recarga la página con Ctrl+F5.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true,raw:true});const sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true});let headerAt=-1,map={};const aliases={agent:['AGENTE','NOMBRE','NOMBRE Y APELLIDOS','APELLIDOS Y NOMBRE','TRABAJADOR','EMPLEADO','AGENT','NOMBRE COMPLETO','COLABORADOR'],company:['SOCIEDAD','EMPRESA','COMPANY','RAZON SOCIAL','RAZÓN SOCIAL','ENTIDAD'],email:['MAIL','EMAIL','CORREO','CORREO ELECTRONICO','CORREO CORPORATIVO','MAIL CORPORATIVO','E MAIL'],hire_date:['FECHA ALTA','FECHA DE ALTA','FECHA INCORPORACION','FECHA DE INCORPORACION','FECHA INGRESO','FECHA DE INGRESO','ALTA','FECHA INICIO'],termination_date:['FECHA DE BAJA','FECHA BAJA','FECHA FINALIZACION','FECHA DE FINALIZACION','FECHA FIN','BAJA'],termination_reason:['MOTIVO','MOTIVO BAJA','MOTIVO DE BAJA','CAUSA BAJA']};for(let i=0;i<Math.min(rows.length,20);i++){const h=rows[i].map(String);const candidate={};Object.keys(aliases).forEach(k=>candidate[k]=findHeader(h,aliases[k]));if(candidate.agent>=0&&candidate.company>=0&&candidate.hire_date>=0){headerAt=i;map=candidate;break;}}if(headerAt<0)throw Error('No identifico las columnas obligatorias: nombre, sociedad y fecha de alta. Comprueba que los encabezados estén en una de las primeras 20 filas.');const parsed=rows.slice(headerAt+1).filter(r=>r.some(v=>String(v??'').trim())).map((r,i)=>{const agent=String(r[map.agent]??'').trim(),raw=String(r[map.company]??'').trim(),company=normalizeCompany(raw),email=map.email>=0?(String(r[map.email]??'').trim().toLowerCase()||'-'):'-',hire=excelDate(r[map.hire_date]),term=map.termination_date>=0?excelDate(r[map.termination_date]):null,reason=map.termination_reason>=0?String(r[map.termination_reason]??'').trim():'',errors=[];if(!agent)errors.push('Falta nombre');if(!company)errors.push('Sociedad no reconocida: '+(raw||'vacía'));if(!hire||hire==='INVALID')errors.push('Fecha de alta no válida');if(term==='INVALID')errors.push('Fecha de baja no válida');if(term&&hire&&term<hire)errors.push('Baja anterior al alta');if(email!=='-'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))errors.push('Mail no válido');return {agent,company:company||raw,email,hire_date:hire,termination_date:term==='INVALID'?null:term,termination_reason:reason||null,errors,row:headerAt+i+2};});if(!parsed.length)throw Error('El Excel no contiene filas de trabajadores.');const invalid=parsed.filter(x=>x.errors.length);window.pendingWorkersImport=parsed.filter(x=>!x.errors).map(({errors,row,...x})=>x);status.textContent=parsed.length+' filas leídas · '+invalid.length+' con errores · '+window.pendingWorkersImport.length+' listas para importar.';preview.innerHTML='<div class="card tablewrap" style="max-height:260px;overflow:auto"><table class="table"><thead><tr><th>Nombre</th><th>Sociedad</th><th>Mail</th><th>Alta</th><th>Baja</th><th>Motivo</th><th>Validación</th></tr></thead><tbody>'+parsed.slice(0,150).map(x=>'<tr><td>'+esc(x.agent||'-')+'</td><td>'+esc(x.company||'-')+'</td><td>'+esc(x.email)+'</td><td>'+esc(x.hire_date||'-')+'</td><td>'+esc(x.termination_date||'-')+'</td><td>'+esc(x.termination_reason||'-')+'</td><td><span class="pill '+(x.errors.length?'red':'green')+'">'+esc(x.errors.join(', ')||'Correcto')+'</span></td></tr>').join('')+'</tbody></table></div><small>Vista previa de hasta 150 filas. Las celdas vacías se muestran como «-» cuando corresponde.</small>';btn.disabled=!window.pendingWorkersImport.length;if(invalid.length)status.textContent+=' Corrige las filas con errores en el Excel y vuelve a seleccionarlo.';else status.textContent+=' Puedes importar los registros.';}catch(err){status.textContent='No se ha podido leer el Excel: '+err.message;btn.disabled=true;}}
async function previewExcel(e){await previewExcelRaw(e);const status=$('workersImportStatus'),btn=$('confirmWorkersImport'),rows=window.pendingWorkersImport||[];if(!rows.length||!client())return;try{const {data,error}=await client().from('workers').select('agent,company,email,hire_date');if(error)throw error;const keyOf=x=>x.email&&x.email!=='-'?'mail:'+String(x.email).trim().toLowerCase():'row:'+norm(x.agent)+'|'+norm(x.company)+'|'+x.hire_date,existing=new Set((data||[]).map(keyOf)),seen=new Set(),dupes=new Set();rows.forEach(x=>{const key=keyOf(x);if(existing.has(key)||seen.has(key))dupes.add(key);seen.add(key);});if(!dupes.size)return;window.pendingWorkersImport=rows.filter(x=>!dupes.has(keyOf(x)));const tr=[...$('workersImportPreview').querySelectorAll('tbody tr')];tr.forEach(row=>{const cells=row.cells,item=rows.find(x=>x.agent===cells[0]?.textContent&&x.company===cells[1]?.textContent&&x.email===cells[2]?.textContent);if(item&&dupes.has(keyOf(item))){const badge=cells[6]?.querySelector('.pill');if(badge){badge.className='pill amber';badge.textContent='Duplicado; se omitirá';}}});status.textContent+=' '+dupes.size+' registro(s) duplicado(s) detectados; se omitirán. '+window.pendingWorkersImport.length+' listos para importar.';btn.disabled=!window.pendingWorkersImport.length;}catch(err){window.pendingWorkersImport=[];btn.disabled=true;status.textContent='No se pudieron comprobar duplicados en Supabase: '+err.message;}}
async function saveWorkersExcel(){const btn=$('confirmWorkersImport'),status=$('workersImportStatus'),rows=window.pendingWorkersImport||[];if(!rows.length){status.textContent='No hay filas válidas para importar.';return;}if(!client()){status.textContent='No hay conexión con Supabase. Cierra sesión y vuelve a entrar.';return;}btn.disabled=true;btn.textContent='Importando…';status.textContent='Comprobando duplicados…';try{const {data:existing,error}=await client().from('workers').select('agent,company,email,hire_date');if(error)throw error;const keys=new Set((existing||[]).map(x=>x.email&&x.email!=='-'?'mail:'+x.email.toLowerCase():'row:'+norm(x.agent)+'|'+norm(x.company)+'|'+x.hire_date));const unique=[];let skipped=0;for(const row of rows){const key=row.email&&row.email!=='-'?'mail:'+row.email.toLowerCase():'row:'+norm(row.agent)+'|'+norm(row.company)+'|'+row.hire_date;if(keys.has(key)){skipped++;continue;}keys.add(key);unique.push({agent:row.agent,company:row.company,email:row.email||'-',hire_date:row.hire_date,termination_date:row.termination_date||null,termination_reason:row.termination_reason||null});}if(!unique.length)throw Error('Todos los registros del Excel ya existen en la plantilla. No se ha añadido ninguno.');let added=0,failures=[];for(let i=0;i<unique.length;i+=25){const batch=unique.slice(i,i+25);status.textContent='Importando '+Math.min(i+batch.length,unique.length)+' de '+unique.length+' trabajadores…';const {error:batchError}=await client().from('workers').insert(batch);if(!batchError){added+=batch.length;continue;}for(let j=0;j<batch.length;j++){const {error:rowError}=await client().from('workers').insert(batch[j]);if(rowError)failures.push(batch[j].agent+': '+rowError.message);else added++;}}await loadAll();if(failures.length){status.textContent='Importación parcial: '+added+' añadidos, '+skipped+' duplicados omitidos y '+failures.length+' con error. Primer error: '+failures[0];btn.disabled=false;btn.textContent='Reintentar filas con error';window.pendingWorkersImport=unique.filter(x=>failures.some(f=>f.startsWith(x.agent+':')));}else{status.textContent='Importación completada: '+added+' trabajadores añadidos; '+skipped+' duplicados omitidos.';btn.textContent='Importación completada';window.pendingWorkersImport=[];setTimeout(closeModal,1400);}}catch(err){status.textContent='No se ha podido importar: '+(err.message||String(err))+' Si aparece un error de permisos o tabla inexistente, hay que revisar la configuración de Supabase.';btn.disabled=false;btn.textContent='Reintentar importación';}}
function vacationEntitlement(w,year){const start=new Date(year,0,1),end=new Date(year,11,31),hire=w.hire_date?new Date(w.hire_date+'T12:00:00'):start,effective=hire>start?hire:start;if(effective>end)return {total:0,weeks:0,singles:0};const daysInYear=Math.round((end-start)/86400000)+1,eligibleDays=Math.round((end-effective)/86400000)+1,total=Math.round(32*eligibleDays/daysInYear),weeks=Math.min(28,Math.floor(total/7)*7);return {total,weeks,singles:total-weeks};}
function vacationQuota(w,year,kind){const q=vacationEntitlement(w,year);return kind==='week'?q.weeks:q.singles;}
function renderVacations(){const year=state.calendarYear,yearRows=state.vacations.filter(v=>v.start_date.slice(0,4)===String(year)),filteredRows=yearRows.filter(v=>overlapsRange(v.start_date,v.end_date,'vacations')),used=filteredRows.reduce((s,v)=>s+Number(v.days_count||0),0),upcoming=filteredRows.filter(v=>v.end_date>=today()).length;const rows=state.workers.map(w=>{const weekQuota=vacationQuota(w,year,'week'),singleQuota=vacationQuota(w,year,'single'),weekUsed=yearRows.filter(v=>v.worker_id===w.id&&v.kind==='week').reduce((s,v)=>s+Number(v.days_count||0),0),singleUsed=yearRows.filter(v=>v.worker_id===w.id&&v.kind==='single').reduce((s,v)=>s+Number(v.days_count||0),0),rangeUsed=filteredRows.filter(v=>v.worker_id===w.id),remaining=Math.max(0,weekQuota-weekUsed)+Math.max(0,singleQuota-singleUsed);if(state.filters.vacations&&!rangeUsed.length)return '';return '<tr><td>'+esc(w.agent)+'</td><td>'+esc(w.company)+'</td><td>'+weekQuota+' + '+singleQuota+'</td><td>'+weekUsed+'</td><td>'+singleUsed+'</td><td>'+remaining+'</td><td><button class="btn" onclick="showVacationHistory(\''+w.id+'\')">Detalle</button></td></tr>';}).filter(Boolean);return '<div class="grid stats">'+stat('Asignación anual','32 días','28 días en semanas + 4 sueltos')+stat('Días disfrutados',used,'En '+year)+stat('Vacaciones próximas',upcoming,'Registros futuros')+stat('Trabajadores',state.workers.length,'En plantilla')+'</div>'+dateFilter('vacations')+table(['Trabajador','Sociedad','Asignados (semana + sueltos)','Semanas usadas','Días sueltos usados','Disponibles','Detalle'],rows,'Todavía no hay vacaciones en el intervalo seleccionado.')+'<div class="notice">El derecho se prorratea por días reales del año, incluido el día de alta; se redondea al entero más cercano y primero se asignan semanas completas de 7 días. No se trasladan días al año siguiente.</div>'+calendar();}
function showVacationHistory(id){const rows=state.vacations.filter(v=>v.worker_id===id);modal('Vacaciones · '+workerName(id),rows.length?rows.map(v=>'<div class="detailrow"><span>'+fmt(v.start_date)+' al '+fmt(v.end_date)+' · '+(v.kind==='week'?'Semana':'Días sueltos')+'</span><b>'+v.days_count+' días</b><span class="actions">'+actionDelete('vacation_records',v.id)+'</span></div>').join(''):'<p>No hay vacaciones registradas.</p>');}
function calendar(){const first=new Date(state.calendarYear,state.calendarMonth,1),last=new Date(state.calendarYear,state.calendarMonth+1,0),offset=(first.getDay()+6)%7;let cells='';for(let i=0;i<offset;i++)cells+='<span></span>';for(let d=1;d<=last.getDate();d++){const date=isoDate(new Date(state.calendarYear,state.calendarMonth,d));const has=state.vacations.some(v=>v.start_date<=date&&v.end_date>=date);cells+='<button aria-label="'+d+(has?', hay vacaciones':'')+'" class="'+(has?'hasvac':'')+'" onclick="calendarDay('+d+')">'+d+'</button>';}return '<div class="card panel" style="margin-top:15px"><div style="display:flex;justify-content:space-between;align-items:center"><h3>'+first.toLocaleDateString('es-ES',{month:'long',year:'numeric'})+'</h3><div><button class="btn" aria-label="Mes anterior" onclick="changeMonth(-1)">‹</button> <button class="btn" aria-label="Mes siguiente" onclick="changeMonth(1)">›</button></div></div><div class="calendar">'+['L','M','X','J','V','S','D'].map(x=>'<span>'+x+'</span>').join('')+cells+'</div></div>';}
function changeMonth(n){state.calendarMonth+=n;if(state.calendarMonth<0){state.calendarMonth=11;state.calendarYear--;}if(state.calendarMonth>11){state.calendarMonth=0;state.calendarYear++;}render();}
function calendarDay(day){const d=isoDate(new Date(state.calendarYear,state.calendarMonth,day));const rows=state.vacations.filter(v=>v.start_date<=d&&v.end_date>=d);modal('Vacaciones · '+fmt(d),rows.length?rows.map(v=>'<div class="detailrow">'+esc(workerName(v.worker_id))+' · '+esc(v.kind==='week'?'Semana':'Días sueltos')+'</div>').join(''):'<p>No hay vacaciones registradas este día.</p>');}
function showVacationForm(){formWrap('Registrar vacaciones',selectField('Trabajador','worker_id',workerOptions())+selectField('Tipo','kind','<option value="week">Semana completa</option><option value="single">Días sueltos</option>')+field('Fecha de inicio','start_date','date')+field('Fecha de fin','end_date','date')+textarea('Observaciones','notes'),'Guardar vacaciones','saveVacation');}
async function saveVacation(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const start=$('start_date').value,end=$('end_date').value;if(end<start)throw Error('La fecha de fin no puede ser anterior al inicio.');if(start.slice(0,4)!==end.slice(0,4))throw Error('Cada registro de vacaciones debe quedar dentro del mismo año natural.');const days=Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1;const w=state.workers.find(x=>x.id===$('worker_id').value);if(!w)throw Error('Selecciona un trabajador.');const year=Number(start.slice(0,4)),kind=$('kind').value;if(state.vacations.some(v=>v.worker_id===w.id&&v.start_date<=end&&v.end_date>=start))throw Error('Este periodo se solapa con otras vacaciones del trabajador.');if(kind==='week'&&(days%7!==0||days<7))throw Error('Las vacaciones de semana deben registrarse en bloques completos de 7 días naturales.');if(kind==='single'&&days!==1)throw Error('Los días sueltos se registran de uno en uno.');const quota=vacationQuota(w,year,kind),usedKind=state.vacations.filter(v=>v.worker_id===w.id&&v.start_date.slice(0,4)===String(year)&&v.kind===kind).reduce((a,v)=>a+Number(v.days_count),0);if(usedKind+days>quota)throw Error('El registro supera los '+quota+' días disponibles en la bolsa '+(kind==='week'?'de semanas':'de días sueltos')+' del año '+year+'.');await insert('vacation_records',{worker_id:w.id,start_date:start,end_date:end,kind:kind,days_count:days,notes:$('notes').value||null});closeModal();await loadAll();toast('Vacaciones registradas.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function showLeaveForm(){formWrap('Nuevo permiso o ausencia',selectField('Trabajador','worker_id',workerOptions())+selectField('Tipo de permiso','leave_type',LEAVE_TYPES.map(x=>'<option>'+x+'</option>').join(''))+selectField('Categoría','category','<option>Retribuido</option><option>Justificado no retribuido</option><option>Injustificado</option><option>Baja médica</option>')+field('Desde','start_date','date')+field('Hasta','end_date','date')+field('Horas (si procede)','hours_count','number',false,'min="0" step="0.25"')+field('Días','days_count','number',false,'min="0" step="0.5" value="1"')+checkbox('Permiso retribuido','is_paid',false)+checkbox('Justificado','is_justified',true)+checkbox('Cuenta para el umbral del bono','counts_for_bonus',false)+textarea('Observaciones','notes'),'Guardar registro','saveLeave');}
async function saveLeave(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const a=$('start_date').value,z=$('end_date').value;if(z<a)throw Error('La fecha final no puede ser anterior a la inicial.');const category=$('category').value,paid=$('is_paid').checked,justified=$('is_justified').checked;await insert('leave_records',{worker_id:$('worker_id').value,leave_type:$('leave_type').value,category,start_date:a,end_date:z,hours_count:$('hours_count').value?Number($('hours_count').value):null,days_count:Number($('days_count').value||1),is_paid:paid,is_justified:justified,counts_for_bonus:$('counts_for_bonus').checked||(!paid&&!justified),notes:$('notes').value||null});closeModal();await loadAll();toast('Permiso o ausencia guardado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function incidentTimingFields(type){return type==='Impuntualidad'?field('Hora prevista de entrada','planned_time','time')+field('Hora real de entrada','incident_time','time'):'<div class="field"><label for="incident_time">Hora de inicio del abandono</label><input id="incident_time" type="time" required></div>'+field('Hora de reincorporación','end_time','time')+'<small>Si la reincorporación es al día siguiente, se calculará correctamente.</small>';}
function updateIncidentFields(){const type=$('incident_type')?.value,box=$('incidentTiming');if(!box)return;box.innerHTML=incidentTimingFields(type)+'<div class="notice" id="incidentDurationPreview">Indica las horas para calcular automáticamente la duración.</div>';['planned_time','incident_time','end_time'].forEach(id=>$(id)?.addEventListener('change',updateIncidentDuration));}
function updateIncidentDuration(){const type=$('incident_type')?.value,planned=$('planned_time')?.value,start=$('incident_time')?.value,end=$('end_time')?.value,preview=$('incidentDurationPreview');if(!preview)return;let mins=null;if(type==='Impuntualidad'&&planned&&start){mins=timeToMinutes(start)-timeToMinutes(planned);if(mins<0){preview.textContent='La hora real es anterior a la hora prevista: se registrarán 0 minutos.';return;} }else if(type==='Abandono de puesto'&&start&&end){mins=timeToMinutes(end)-timeToMinutes(start);if(mins<0)mins+=1440;}if(mins===null){preview.textContent='Indica las horas para calcular automáticamente la duración.';return;}preview.textContent='Duración calculada automáticamente: '+mins+' minutos ('+Math.floor(mins/60)+' h '+(mins%60)+' min).';}
function timeToMinutes(value){const p=value.split(':').map(Number);return p[0]*60+p[1];}
function showIncidentForm(){formWrap('Registrar incidencia',selectField('Trabajador','worker_id',workerOptions())+selectField('Tipo de incidencia','incident_type','<option>Impuntualidad</option><option>Abandono de puesto</option>')+field('Fecha','incident_date','date')+'<div id="incidentTiming">'+incidentTimingFields('Impuntualidad')+'</div>'+checkbox('Justificada','is_justified',false)+checkbox('Cuenta para el umbral del bono','counts_for_bonus',false)+textarea('Observaciones','notes'),'Guardar incidencia','saveIncident');$('incident_type').addEventListener('change',updateIncidentFields);['planned_time','incident_time'].forEach(id=>$(id)?.addEventListener('change',updateIncidentDuration));}
async function saveIncident(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const type=$('incident_type').value,planned=$('planned_time')?.value||null,start=$('incident_time').value,end=$('end_time')?.value||null;let duration=0;if(type==='Impuntualidad'){if(!planned||!start)throw Error('Indica la hora prevista y la hora real de entrada.');duration=Math.max(0,timeToMinutes(start)-timeToMinutes(planned));}else{if(!start||!end)throw Error('Indica la hora de inicio y la hora de reincorporación.');duration=timeToMinutes(end)-timeToMinutes(start);if(duration<0)duration+=1440;}await insert('incident_records',{worker_id:$('worker_id').value,incident_type:type,incident_date:$('incident_date').value,incident_time:start,planned_time:planned,end_time:end,duration_minutes:duration,is_justified:$('is_justified').checked,counts_for_bonus:$('counts_for_bonus').checked,notes:$('notes').value||null});closeModal();await loadAll();toast('Incidencia registrada ('+duration+' minutos).');}catch(err){s.textContent=err.message;b.disabled=false;}}
