async function savePayment(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const row=await insert('additional_payments',{worker_id:$('worker_id').value,concept:$('concept').value.trim(),reference:$('reference').value||null,amount:Number($('amount').value),payment_date:$('payment_date').value,status:$('status').value,notes:$('notes').value||null});if($('make_pending').checked&&$('status').value==='Pendiente'){const due=$('expected_date').value||$('payment_date').value;await insert('pending_payments',{worker_id:row.worker_id,concept:row.concept,amount:row.amount,expected_date:due,additional_payment_id:row.id,notes:'Generado desde pagos adicionales'});}closeModal();await loadAll();toast('Pago adicional guardado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function showPendingForm(){formWrap('Registrar pago pendiente',selectField('Trabajador','worker_id',workerOptions())+field('Concepto','concept')+field('Importe (€)','amount','number',true,'min="0" step="0.01"')+field('Fecha prevista de abono','expected_date','date')+textarea('Observaciones','notes'),'Guardar pendiente','savePending');}
async function savePending(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{await insert('pending_payments',{worker_id:$('worker_id').value,concept:$('concept').value.trim(),amount:Number($('amount').value),expected_date:$('expected_date').value,notes:$('notes').value||null});closeModal();await loadAll();toast('Pago pendiente registrado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
async function markPaid(id){try{await update('pending_payments',id,{status:'Abonado',paid_at:today()});await loadAll();toast('Pago marcado como abonado.');}catch(e){toast(e.message);}}
function renderRows(key,rows,headers,empty){return table(headers,rows,empty);}
function renderLeaves(){const rows=state.leaves.filter(x=>inRange(x.start_date,'leaves')).map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.leave_type)+'</td><td>'+fmt(x.start_date)+'</td><td>'+fmt(x.end_date)+'</td><td>'+esc(x.hours_count?x.hours_count+' h':x.days_count+' días')+'</td><td>'+esc(x.category)+'</td><td>'+esc(x.is_paid?'Retribuido':x.is_justified?'Justificado':'Injustificado')+'</td><td>'+actionDelete('leave_records',x.id)+'</td></tr>');return table(['Trabajador','Tipo','Desde','Hasta','Duración','Categoría','Estado','Acciones'],rows,'Todavía no hay permisos ni ausencias registrados.');}
function renderIncidents(){const rows=state.incidents.filter(x=>inRange(x.incident_date,'incidents')).map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.incident_type)+'</td><td>'+fmt(x.incident_date)+'</td><td>'+esc(x.incident_time||'—')+'</td><td>'+x.duration_minutes+' min</td><td>'+esc(x.notes||'—')+'</td><td>'+esc(x.is_justified?'Justificada':'No justificada')+'</td><td>'+actionDelete('incident_records',x.id)+'</td></tr>');const weeks={};state.incidents.filter(x=>inRange(x.incident_date,'incidents')).forEach(x=>{const d=new Date(x.incident_date+'T12:00:00'),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const k=monday.toLocaleDateString('es-ES');weeks[k]=(weeks[k]||0)+1;});return '<div class="grid stats">'+Object.keys(weeks).map(k=>stat('Semana '+k,weeks[k],'Incidencias')).join('')+'</div>'+table(['Trabajador','Incidencia','Fecha','Hora','Duración','Observaciones','Estado','Acciones'],rows,'Todavía no hay incidencias registradas.');}
function renderPartners(){return '<div class="notice">El incentivo es de 100 € por persona referida. Se incluirá en Pagos adicionales cuando complete su primer mes natural y continúe activa al cierre.</div>'+table(['Comercial referente','Persona referida','Fecha incorporación','Incentivo','Previsión de pago','Acciones'],state.partners.filter(x=>inRange(x.incorporation_date,'partners')).map(x=>{const worker=state.workers.find(w=>w.id===x.referred_worker_id),month=firstFullPayrollMonth(worker),obligation=state.obligations.find(o=>o.partner_record_id===x.id),status=x.status==='Cancelado'?'Cancelado':x.status==='Abonado'?'Abonado':!worker?'Persona sin vincular':!month?'No corresponde':obligation?obligationStatus(obligation):'Previsto';return '<tr><td>'+esc(x.referrer_name)+'</td><td>'+esc(worker?.agent||x.referred_name)+'</td><td>'+fmt(x.incorporation_date)+'</td><td>'+money(100)+'</td><td>'+esc(status)+(month?' · '+fmt(month):'')+'</td><td>'+actionDelete('partner_records',x.id)+'</td></tr>'; }),'Todavía no hay Partners registrados.');}
function renderHours(){return table(['Trabajador','Fecha','Concepto','Horas','Importe','Estado','Acciones'],state.hours.filter(x=>inRange(x.work_date,'hours')).map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+fmt(x.work_date)+'</td><td>'+esc(x.concept)+'</td><td>'+x.hours+'</td><td>'+money(x.amount)+'</td><td>'+esc(x.status)+'</td><td>'+actionDelete('extra_hours',x.id)+'</td></tr>'),'Todavía no hay horas extra registradas.');}
function obligationMonthEnd(month){const d=new Date(month+'T12:00:00');return isoDate(new Date(d.getFullYear(),d.getMonth()+1,0));}
function obligationStatus(item){if(item.status==='Abonado'||item.status==='No corresponde')return item.status;return obligationMonthEnd(item.payroll_month)<=today()?'Pendiente':'Previsto';}
async function markObligationPaid(id){const item=state.obligations.find(x=>x.id===id);if(!item)return;if(obligationStatus(item)!=='Pendiente'){toast('El pago solo se puede marcar como abonado cuando haya terminado el mes completo.');return;}const {error}=await client().from('additional_payment_obligations').update({status:'Abonado',paid_at:today()}).eq('id',id);if(error){toast(error.message);return;}await loadAll();toast('Pago previsto marcado como abonado.');}
function renderPayments(){const f=state.filters.payments||{},within=d=>(!f.from||d>=f.from)&&(!f.to||d<=f.to),regular=state.payments.filter(x=>within(x.payment_date)).map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.concept)+'</td><td>'+esc(x.reference||'—')+'</td><td>'+money(x.amount)+'</td><td>'+fmt(x.payment_date)+'</td><td><span class="pill '+(x.status==='Abonado'?'blue':'amber')+'">'+esc(x.status)+'</span></td><td>'+actionDelete('additional_payments',x.id)+'</td></tr>'),auto=state.obligations.filter(x=>within(x.payroll_month)).map(x=>{const status=obligationStatus(x),person=workerName(x.worker_id),concept=x.obligation_type==='Formación'?'Pago de formación':'Incentivo Partner';return '<tr><td>'+esc(person)+'</td><td>'+concept+'</td><td>'+(x.partner_record_id?'Partner referido':'Nómina')+'</td><td>'+(x.amount===null?'—':money(x.amount))+'</td><td>'+fmt(x.payroll_month)+'</td><td><span class="pill '+(status==='Abonado'?'blue':status==='No corresponde'?'gray':'amber')+'">'+status+'</span></td><td>'+(status==='Pendiente'?'<button class="btn primary" onclick="markObligationPaid(\''+x.id+'\')">Marcar abonado</button>':status==='Previsto'?'<span class="muted">Fin de mes</span>':'')+'</td></tr>';});const rows=auto.concat(regular);return '<div class="notice">Los pagos de formación aparecen como concepto previsto, sin importe. El incentivo Partner se calcula en 100 €. Solo se generan si la persona continúa activa hasta el último día del mes completo.</div>'+table(['Trabajador','Concepto','Origen','Importe','Mes de nómina','Estado','Acciones'],rows,'No hay pagos adicionales ni conceptos previstos en el periodo.');}
function renderPending(){const rows=state.pending.filter(x=>inRange(x.expected_date,'pending')).map(x=>{const age=Math.max(0,Math.floor((new Date(today())-new Date(x.expected_date))/86400000));return '<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.concept)+'</td><td>'+money(x.amount)+'</td><td>'+fmt(x.expected_date)+'</td><td>'+age+' días</td><td>'+esc(x.status)+'</td><td>'+(x.status==='Pendiente'?'<button class="btn primary" onclick="markPaid(\''+x.id+'\')">Marcar abonado</button> ':'')+actionDelete('pending_payments',x.id)+'</td></tr>';});const total=state.pending.filter(x=>x.status==='Pendiente').reduce((s,x)=>s+Number(x.amount),0);return '<div class="grid stats">'+stat('Importe pendiente',money(total),'Total sin abonar')+stat('Registros pendientes',state.pending.filter(x=>x.status==='Pendiente').length,'Pagos abiertos')+'</div>'+table(['Trabajador','Concepto','Importe','Fecha prevista','Antigüedad','Estado','Acciones'],rows,'No hay pagos pendientes registrados.');}
function showBonusPaymentForm(){formWrap('Registrar pago de bono de asistencia',selectField('Trabajador','worker_id',workerOptions())+field('Año del bono','bonus_year','number',true,'min="2000" max="2100" value="'+new Date().getFullYear()+'"')+field('Importe abonado (€)','bonus_amount','number',true,'min="0" step="0.01" value="200"')+field('Fecha de abono','bonus_payment_date','date',true,'value="'+today()+'"')+textarea('Observaciones','bonus_notes'),'Registrar pago','saveBonusPayment');}
async function saveBonusPayment(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const worker=state.workers.find(x=>x.id===$('worker_id').value);if(!worker)throw Error('Selecciona un trabajador.');const year=$('bonus_year').value,amount=Number($('bonus_amount').value);if(!year||!amount||amount<0)throw Error('Indica un año y un importe válido.');await insert('additional_payments',{worker_id:worker.id,concept:'Bono de asistencia '+year,reference:'Bono de asistencia',amount,payment_date:$('bonus_payment_date').value,status:'Abonado',notes:$('bonus_notes').value||null});closeModal();await loadAll();toast('Pago de bono registrado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function renderBonuses(){const rows=state.workers.map(w=>{const l=state.leaves.filter(x=>x.worker_id===w.id&&x.counts_for_bonus&&!x.is_paid).length,i=state.incidents.filter(x=>x.worker_id===w.id&&x.counts_for_bonus).length,total=l+i,lost=total>=3,paid=state.payments.some(p=>p.worker_id===w.id&&String(p.concept||'').toLowerCase().startsWith('bono de asistencia')&&String(p.concept).includes(String(state.calendarYear)));return '<tr><td>'+esc(w.agent)+'</td><td>'+total+'</td><td>'+money(lost?0:200)+'</td><td><span class="pill '+(lost?'red':paid?'blue':'green')+'">'+(lost?'Perdido':paid?'Abonado':'Con derecho')+'</span></td><td><button class="btn" onclick="bonusDetails(\''+w.id+'\')">Ver detalle</button>'+(lost||paid?'':' <button class="btn primary" onclick="showBonusPaymentFormFor(\''+w.id+'\')">Registrar abono</button>')+'</td></tr>';});const lost=state.workers.filter(w=>state.leaves.filter(x=>x.worker_id===w.id&&x.counts_for_bonus&&!x.is_paid).length+state.incidents.filter(x=>x.worker_id===w.id&&x.counts_for_bonus).length>=3).length;return '<div class="grid stats">'+stat('Importe del bono','200 €','Por trabajador')+stat('Umbral de ausencias','3','Ausencias computables')+stat('Bonos perdidos',lost,'Según los registros actuales')+'</div>'+table(['Trabajador','Ausencias computables','Importe','Estado del bono','Acciones'],rows,'Todavía no hay trabajadores registrados.')+'<div class="notice">Se cuentan las ausencias marcadas expresamente como computables para el bono y que no sean retribuidas. Las impuntualidades y abandonos solo cuentan si se marca esa opción al registrarlos. El abono queda registrado en Pagos adicionales.</div>';}
function bonusDetails(id){const items=state.leaves.filter(x=>x.worker_id===id&&x.counts_for_bonus&&!x.is_paid).map(x=>'<div class="detailrow">'+esc(x.leave_type)+' · '+fmt(x.start_date)+' · '+esc(x.category)+'</div>').concat(state.incidents.filter(x=>x.worker_id===id&&x.counts_for_bonus).map(x=>'<div class="detailrow">'+esc(x.incident_type)+' · '+fmt(x.incident_date)+'</div>'));modal('Detalle del bono · '+workerName(id),items.join('')||'<p>No hay ausencias computables.</p>');}
const reportFieldLabels={date:'Fecha',area:'Área',person:'Persona',concept:'Concepto',detail:'Detalle',amount:'Importe',status:'Estado'};
function analysisRows(){const q=state.analysis,from=q.from||isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1)),to=q.to||today(),area=q.area||'all',society=q.society||'',rows=[];const inDates=(d,end=d)=>end>=from&&d<=to;const companyFor=id=>state.workers.find(w=>w.id===id)?.company||'';const add=(r)=>{if(!inDates(r.date,r.endDate||r.date))return;if(society&&companyFor(r.workerId)!==society)return;if(area!=='all'&&area!==r.area)return;rows.push(r);};
 for(const w of state.workers){if(inDates(w.hire_date))add({date:w.hire_date,area:'workers',workerId:w.id,person:w.agent,concept:'Alta de trabajador',detail:w.company,amount:null,status:'Registrado'});if(w.termination_date&&inDates(w.termination_date))add({date:w.termination_date,area:'workers',workerId:w.id,person:w.agent,concept:'Baja de trabajador',detail:w.termination_reason||'—',amount:null,status:'Registrado'});}
 for(const x of state.vacations)add({date:x.start_date,endDate:x.end_date,area:'vacations',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.kind==='week'?'Vacaciones · semana':'Vacaciones · días sueltos',detail:fmt(x.start_date)+'–'+fmt(x.end_date)+' · '+x.days_count+' días',amount:null,status:'Registrado'});
 for(const x of state.leaves)add({date:x.start_date,endDate:x.end_date,area:'leaves',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.leave_type,detail:x.hours_count?x.hours_count+' horas':x.days_count+' días',amount:null,status:x.is_paid?'Retribuido':x.is_justified?'Justificado':'Injustificado'});
 for(const x of state.incidents)add({date:x.incident_date,area:'leaves',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.incident_type,detail:x.duration_minutes+' min · '+(x.notes||'—'),amount:null,status:x.is_justified?'Justificada':'No justificada'});
 for(const x of state.partners)add({date:x.incorporation_date,area:'partners',workerId:x.referred_worker_id,person:x.referred_name,concept:'Alta de Partner',detail:'Referente: '+x.referrer_name+' · incentivo previsto al primer mes completo',amount:null,status:x.status});
 for(const x of state.hours)add({date:x.work_date,area:'hours',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:x.hours+' horas',amount:Number(x.amount||0),status:x.status});
 for(const x of state.payments)add({date:x.payment_date,area:'payments',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:x.reference||'—',amount:Number(x.amount||0),status:x.status});
 for(const x of state.pending)add({date:x.expected_date,area:'pending',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:'Fecha prevista de abono',amount:Number(x.amount||0),status:x.status});
 for(const x of state.obligations){const status=obligationStatus(x);if(status==='No corresponde')continue;const person=workerName(x.worker_id),concept=x.obligation_type==='Formación'?'Pago de formación':'Incentivo Partner';add({date:x.payroll_month,area:'payments',workerId:x.worker_id,person,concept,detail:x.obligation_type==='Formación'?'Corresponde en la primera nómina mensual completa':'Incentivo Partner · primer mes de nómina completa',amount:x.amount===null?null:Number(x.amount),status});}
 return rows.sort((a,b)=>a.date.localeCompare(b.date)||a.person.localeCompare(b.person,'es'));
}
function analysisForm(){if(!state.analysis.from)state.analysis.from=isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1));if(!state.analysis.to)state.analysis.to=today();const societyOptions='<option value="">Todas las sociedades</option>'+state.societies.map(s=>'<option value="'+esc(s.name)+'" '+(state.analysis.society===s.name?'selected':'')+'>'+esc(s.name)+'</option>').join(''),areas=[['all','Todo el sistema'],['workers','Trabajadores'],['vacations','Vacaciones'],['leaves','Permisos e incidencias'],['partners','Partners'],['hours','Horas extra'],['payments','Pagos adicionales'],['pending','Pagos pendientes']];const selected=state.analysis.fields||Object.keys(reportFieldLabels);const fields=Object.entries(reportFieldLabels).map(([key,label])=>'<label class="report-field"><input type="checkbox" name="reportField" value="'+key+'" '+(selected.includes(key)?'checked':'')+'> '+label+'</label>').join('');return '<form id="analysisForm" class="analysis-filters"><div class="field"><label for="analysisFrom">Desde</label><input id="analysisFrom" type="date" value="'+state.analysis.from+'" required></div><div class="field"><label for="analysisTo">Hasta</label><input id="analysisTo" type="date" value="'+state.analysis.to+'" required></div><div class="field"><label for="analysisArea">Área</label><select id="analysisArea">'+areas.map(([key,label])=>'<option value="'+key+'" '+((state.analysis.area||'all')===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div><div class="field"><label for="analysisSociety">Sociedad</label><select id="analysisSociety">'+societyOptions+'</select></div><details class="report-fields"><summary>Elegir campos del informe</summary><div class="report-field-list">'+fields+'</div></details><button class="btn" type="submit">'+icon('check')+'Aplicar filtros</button><button class="btn primary" type="button" onclick="exportAnalysisPdf()">'+icon('download')+'Exportar PDF</button></form>';}
function renderAnalysis(){if(!state.analysis.from)state.analysis.from=isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1));if(!state.analysis.to)state.analysis.to=today();const rows=analysisRows(),fields=state.analysis.fields||Object.keys(reportFieldLabels),areaLabels={all:'Todo el sistema',workers:'Trabajadores',vacations:'Vacaciones',leaves:'Permisos e incidencias',partners:'Partners',hours:'Horas extra',payments:'Pagos adicionales',pending:'Pagos pendientes'},amount=rows.reduce((s,x)=>s+(x.amount===null?0:Number(x.amount)||0),0),columns=fields.map(k=>'<th>'+reportFieldLabels[k]+'</th>').join(''),body=rows.length?rows.map(r=>'<tr>'+fields.map(k=>'<td>'+esc(k==='date'?fmt(r.date):k==='area'?areaLabels[r.area]:k==='person'?r.person:k==='concept'?r.concept:k==='detail'?r.detail:k==='amount'?r.amount===null?'—':money(r.amount):r.status)+'</td>').join('')+'</tr>').join(''):'<tr><td class="empty-state" colspan="'+Math.max(fields.length,1)+'"><div class="empty-icon">'+icon('file')+'</div><strong>No hay datos en el intervalo elegido.</strong></td></tr>';const from=state.analysis.from,to=state.analysis.to,society=state.analysis.society||'Todas las sociedades';return header('INFORMES','Análisis','Filtra los registros de Acerca y prepara un informe en PDF.','')+analysisForm()+'<div class="grid stats analysis-stats">'+stat('Registros incluidos',rows.length,'Con los filtros aplicados')+stat('Importes cuantificados',money(amount),'Los conceptos sin cuantía no se suman')+stat('Área',areaLabels[state.analysis.area||'all'],society)+'</div><div class="card tablewrap analysis-table"><table class="table"><thead><tr>'+columns+'</tr></thead><tbody>'+body+'</tbody></table></div><div id="printReport" class="print-report"><div class="print-brand">ACERCA · GESTIÓN INTERNA</div><h1>Informe de análisis</h1><p>Periodo: '+fmt(from)+' – '+fmt(to)+' · Área: '+esc(areaLabels[state.analysis.area||'all'])+' · Sociedad: '+esc(society)+'</p><p>'+rows.length+' registros · Importe cuantificado: '+money(amount)+'</p><table><thead><tr>'+columns+'</tr></thead><tbody>'+body+'</tbody></table><footer>Informe generado el '+fmt(today())+' · Uso interno ACERCA</footer></div>';}
function collectAnalysisFilters(){const from=$('analysisFrom').value,to=$('analysisTo').value;if(!from||!to||from>to){toast('Comprueba el intervalo de fechas.');return false;}const fields=[...document.querySelectorAll('#analysisForm [name="reportField"]:checked')].map(x=>x.value);if(!fields.length){toast('Selecciona al menos un campo para el informe.');return false;}state.analysis={from,to,area:$('analysisArea').value,society:$('analysisSociety').value,fields};return true;}
function applyAnalysisFilters(event){event.preventDefault();if(collectAnalysisFilters())render();}
function exportAnalysisPdf(){if($('analysisForm')&&!collectAnalysisFilters())return;render();window.print();}
function nextWeek(){const d=new Date();d.setHours(12,0,0,0);const delta=7-((d.getDay()+6)%7);d.setDate(d.getDate()+delta);const start=isoDate(d);d.setDate(d.getDate()+6);return {start,end:isoDate(d)};}
function showUpcomingVacations(){const range=nextWeek(),rows=state.vacations.filter(v=>v.start_date<=range.end&&v.end_date>=range.start).map(v=>'<tr><td>'+esc(workerName(v.worker_id))+'</td><td>'+esc(state.workers.find(w=>w.id===v.worker_id)?.company||'—')+'</td><td>'+fmt(v.start_date)+'</td><td>'+fmt(v.end_date)+'</td></tr>');modal('Vacaciones próximas · '+fmt(range.start)+'–'+fmt(range.end),table(['Trabajador','Sociedad','Desde','Hasta'],rows,'No hay vacaciones en la semana siguiente.'));}
function renderHome(){const active=state.workers.filter(w=>!w.termination_date||w.termination_date>=today()).length,pending=state.pending.filter(x=>x.status==='Pendiente').reduce((s,x)=>s+Number(x.amount),0),range=nextWeek(),upcomingWorkers=new Set(state.vacations.filter(v=>v.start_date<=range.end&&v.end_date>=range.start).map(v=>v.worker_id)).size,month=today().slice(0,7),obligations=state.obligations.filter(x=>x.payroll_month.slice(0,7)===month&&obligationStatus(x)!=='Abonado'&&obligationStatus(x)!=='No corresponde').length;return header('RESUMEN GENERAL','Bienvenido a Acerca','Resumen actualizado de la gestión interna.','<button class="btn" onclick="go(\'analisis\')">'+icon('file')+' Abrir análisis</button>')+'<div class="grid stats">'+stat('Trabajadores activos',active,'En plantilla')+stat('Vacaciones próximas',upcomingWorkers,fmt(range.start)+'–'+fmt(range.end),'showUpcomingVacations()')+stat('Incidencias este mes',state.incidents.filter(x=>x.incident_date.slice(0,7)===today().slice(0,7)).length,'Impuntualidades y abandonos')+stat('Pagos pendientes',money(pending),'Importe por abonar')+'</div>'+(obligations?'<div class="card wide"><div><b>Pagos de nómina previstos</b><small>'+obligations+' conceptos automáticos corresponden este mes. Consulta la previsión y el informe completo.</small></div><button class="btn primary" onclick="go(\'pagos\')">Ver pagos adicionales</button></div>':'');}
function renderConfig(){const rows=state.societies.map(x=>'<div class="detailrow"><span>'+esc(x.name)+(x.active?'':' · Inactiva')+'</span><span class="actions"><button class="btn" data-society-action="edit" data-society-name="'+esc(x.name)+'">Editar</button><button class="btn" data-society-action="toggle" data-society-name="'+esc(x.name)+'">'+(x.active?'Desactivar':'Activar')+'</button></span></div>').join('');return header('SISTEMA','Configuración','Gestiona el catálogo de sociedades.')+'<div class="card panel"><div class="head"><div><h3>Sociedades</h3><p>Las sociedades con trabajadores asociados se conservan en el historial.</p></div><button class="btn primary" onclick="showSocietyForm()">'+icon('plus')+' Añadir sociedad</button></div>'+(rows||'<p>Todavía no hay sociedades configuradas.</p>')+'</div>'+(state.societies.length?'':'<div class="notice">Configura al menos una sociedad antes de crear o importar trabajadores.</div>');}
function render(){
 $('crumb').textContent=titles[state.page];document.querySelectorAll('#mainNav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));
 const v=$('view');let html='';
 switch(state.page){
 case 'inicio':html=renderHome();break;
 case 'trabajadores':html=header('GENERAL','Trabajadores','Gestiona las fichas y los datos básicos de la plantilla.','<button class="btn" onclick="showExcelImport()">Importar Excel</button><button class="btn primary" onclick="showNewWorker()">+ Nuevo trabajador</button>')+dateFilter('workers')+renderWorkers();break;
 case 'vacaciones':html=header('GESTIÓN LABORAL','Vacaciones','Registra y consulta semanas completas y días sueltos.','<button class="btn primary" onclick="showVacationForm()">+ Registrar vacaciones</button>')+renderVacations();break;
 case 'permisos':html=header('GESTIÓN LABORAL','Permisos y ausencias','Registra permisos retribuidos, ausencias y bajas.','<button class="btn primary" onclick="showLeaveForm()">+ Nuevo registro</button>')+'<div class="grid stats">'+stat('Horas médicas',state.leaves.filter(x=>x.leave_type==='Horas médicas').reduce((s,x)=>s+Number(x.hours_count||0),0)+' h','36 horas anuales de referencia')+stat('Fuerza mayor',state.leaves.filter(x=>x.leave_type==='Fuerza mayor').reduce((s,x)=>s+Number(x.days_count||0),0)+' días','4 días anuales de referencia')+stat('Ausencias',state.leaves.filter(x=>!x.is_paid).length,'No retribuidas')+'</div>'+dateFilter('leaves')+renderLeaves();break;
 case 'incidencias':html=header('GESTIÓN LABORAL','Impuntualidades y abandonos','Control mensual con resúmenes semanales.','<button class="btn primary" onclick="showIncidentForm()">+ Registrar incidencia</button>')+dateFilter('incidents')+renderIncidents();break;
 case 'partners':html=header('GESTIÓN ECONÓMICA','Partners','Registra referencias comerciales e incentivos.','<button class="btn primary" onclick="showPartnerForm()">+ Registrar Partner</button>')+dateFilter('partners')+renderPartners();break;
 case 'horas':html=header('GESTIÓN ECONÓMICA','Horas extra','Control de sábados voluntarios y remuneraciones.','<button class="btn primary" onclick="showHoursForm()">+ Registrar horas</button>')+dateFilter('hours')+renderHours();break;
 case 'pagos':html=header('GESTIÓN ECONÓMICA','Pagos adicionales','Registra facturas, incentivos y otros importes.','<button class="btn primary" onclick="showPaymentForm()">+ Registrar pago</button>')+dateFilter('payments')+renderPayments();break;
 case 'pendientes':html=header('GESTIÓN ECONÓMICA','Pagos pendientes','Consulta y controla los importes pendientes.','<button class="btn primary" onclick="showPendingForm()">+ Registrar pendiente</button>')+dateFilter('pending')+renderPending();break;
 case 'bonos':html=header('GESTIÓN ECONÓMICA','Bonos de asistencia','Seguimiento individual de los bonos.','<button class="btn primary" onclick="showBonusPaymentForm()">+ Registrar pago de bono</button>')+renderBonuses();break;
 case 'analisis':html=renderAnalysis();break;
 case 'configuracion':html=renderConfig();break;
 }
 v.innerHTML=html;
 v.querySelectorAll('[data-society-action]').forEach(button=>button.addEventListener('click',()=>button.dataset.societyAction==='edit'?showSocietyForm(button.dataset.societyName):toggleSociety(button.dataset.societyName)));
 const analysisFormElement=v.querySelector('#analysisForm');if(analysisFormElement)analysisFormElement.addEventListener('submit',applyAnalysisFilters);
}
function go(p){state.page=p;render();$('sidebar').classList.remove('open');window.scrollTo(0,0);}
function removeRecord(t,id){remove(t,id);}
document.querySelectorAll('#mainNav button[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
$('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal();});
window.initAcercaApp=async function(){await loadAll();};
window.refreshWorkers=async function(){const {data,error}=await client().from('workers').select('*').order('agent');if(error)throw error;state.workers=data||[];render();};
window.closeModal=closeModal;window.showBonusPaymentForm=showBonusPaymentForm;window.showNewWorker=showNewWorker;window.showExcelImport=showExcelImport;window.downloadWorkersTemplate=downloadWorkersTemplate;window.editWorker=editWorker;window.saveWorkerEdit=saveWorkerEdit;window.showSocietyForm=showSocietyForm;window.saveSociety=saveSociety;window.toggleSociety=toggleSociety;window.showUpcomingVacations=showUpcomingVacations;window.showVacationForm=showVacationForm;window.showLeaveForm=showLeaveForm;window.showIncidentForm=showIncidentForm;window.showPartnerForm=showPartnerForm;window.showHoursForm=showHoursForm;window.showPaymentForm=showPaymentForm;window.showPendingForm=showPendingForm;window.previewExcel=previewExcel;window.saveWorkersExcel=saveWorkersExcel;window.applyFilter=applyFilter;window.resetFilter=resetFilter;window.saveWorker=saveWorker;window.saveVacation=saveVacation;window.saveLeave=saveLeave;window.saveIncident=saveIncident;window.savePartner=savePartner;window.saveHours=saveHours;window.savePayment=savePayment;window.savePending=savePending;window.saveBonusPayment=saveBonusPayment;window.markPaid=markPaid;window.markObligationPaid=markObligationPaid;window.exportAnalysisPdf=exportAnalysisPdf;window.removeRecord=removeRecord;window.bonusDetails=bonusDetails;window.showVacationHistory=showVacationHistory;window.updateIncidentFields=updateIncidentFields;window.showBonusPaymentFormFor=id=>{showBonusPaymentForm();$('worker_id').value=id;};window.calendarDay=calendarDay;window.changeMonth=changeMonth;
render();
